33 | /**
34 |  * <p>
35 |  * A specialized hierarchical configuration class that is able to parse YAML
36 |  * documents.
37 |  * </p>
38 |  *
39 |  * @since 2.2
40 |  */
41 | public class YAMLConfiguration extends AbstractYAMLBasedConfiguration
42 |         implements FileBasedConfiguration, InputStreamSupport
43 | {
44 |     /**
45 |      * Creates a new instance of {@code YAMLConfiguration}.
46 |      */
47 |     public YAMLConfiguration()
48 |     {
49 |         super();
50 |     }
51 | 
52 |     /**
53 |      * Creates a new instance of {@code YAMLConfiguration} as a copy of the
54 |      * specified configuration.
55 |      *
56 |      * @param c the configuration to be copied
57 |      */
58 |     public YAMLConfiguration(final HierarchicalConfiguration<ImmutableNode> c)
59 |     {
60 |         super(c);
61 |     }
62 | 
63 |     @Override
64 |     public void read(final Reader in) throws ConfigurationException
65 |     {
66 |         try
67 |         {
68 |             final Yaml yaml = new Yaml();
69 |             final Map<String, Object> map = (Map) yaml.load(in);
70 |             load(map);
71 |         }
72 |         catch (final Exception e)
73 |         {
74 |             rethrowException(e);
75 |         }
76 |     }
77 | 
78 |     public void read(final Reader in, final LoaderOptions options)
79 |             throws ConfigurationException
80 |     {
81 |         try
82 |         {
83 |             final Yaml yaml = new Yaml(options);
84 |             final Map<String, Object> map = (Map) yaml.load(in);
85 |             load(map);
86 |         }
87 |         catch (final Exception e)
88 |         {
89 |             rethrowException(e);
90 |         }
91 |     }
92 | 
93 |     @Override
94 |     public void write(final Writer out) throws ConfigurationException, IOException
95 |     {
96 |         final DumperOptions options = new DumperOptions();
97 |         options.setDefaultFlowStyle(DumperOptions.FlowStyle.BLOCK);
98 |         dump(out, options);
99 |     }
100 | 
101 |     public void dump(final Writer out, final DumperOptions options)
102 |             throws ConfigurationException, IOException
103 |     {
104 |         final Yaml yaml = new Yaml(options);
105 |         yaml.dump(constructMap(getNodeModel().getNodeHandler().getRootNode()),
106 |                 out);
107 |     }
108 | 
109 |     /**
110 |      * Loads the configuration from the given input stream.
111 |      *
112 |      * @param in the input stream
113 |      * @throws ConfigurationException if an error occurs
114 |      */
115 |     @Override
116 |     public void read(final InputStream in) throws ConfigurationException
117 |     {
118 |         try
119 |         {
120 |             final Yaml yaml = new Yaml();
